class Report:
    def __init__(self, title, content):
        self.title = title
        self.content = content

    def generate_report(self):
        return f"Title: {self.title}
Content: {self.content}"

class ReportPrinter:
    @staticmethod
    def print_report(report):
        print(report.generate_report())

# Usage
report = Report("Monthly Sales", "Sales data for the month.")
ReportPrinter.print_report(report)

import java.util.Scanner;

public class AddTwoNumbers {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter first number: ");
        int num1 = scanner.nextInt();

        System.out.print("Enter second number: ");
        int num2 = scanner.nextInt();

        int sum = num1 + num2;

        System.out.println("The sum is: " + sum);

        scanner.close();
    }
}

#include <iostream>
using namespace std;

int main() {
    int var = 42;          // An integer variable
    int* ptr = &var;      // Pointer to the variable's address

    cout << "Value of var: " << var << endl;         // Outputs 42
    cout << "Address of var: " << &var << endl;      // Outputs the address of var
    cout << "Value via pointer: " << *ptr << endl;   // Outputs 42 (dereferencing the pointer)

    return 0;
}

def binary_search(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2  # Avoids overflow

        if arr[mid] == target:
            return mid  # Target found
        elif arr[mid] < target:
            left = mid + 1  # Search right half
        else:
            right = mid - 1  # Search left half

    return -1  # Target not found

# Example usage
sorted_array = [1, 3, 5, 7, 9]
target_value = 5
result = binary_search(sorted_array, target_value)
print(result)  # Output: 2 (index of target_value)

public class SubtractionExample {
    public static void main(String[] args) {
        int a = 10;
        int b = 5;
        int result = a - b;
        System.out.println("Subtraction Result: " + result);
    }
}
